import os
import pandas as pd
import numpy as np

# ==============================================================================
# CONFIGURATION
# ==============================================================================
# Mettez ici le chemin du dossier contenant TOUS vos fichiers Excel/CSV
DATA_FOLDER = (
    r"C:\Users\gabri\OneDrive - Groupe INSEEC (POCE)\ING5\S1\PFE\CSV\OWUFolder"
)


class Tools:
    def __init__(self):
        pass

    # ------------------------------------------------------------------------
    # 1. EXPLORATION (La capacité de voir ce qui est dispo)
    # ------------------------------------------------------------------------
    def list_available_datasets(self) -> dict:
        """
        Liste tous les fichiers CSV ou Excel disponibles dans le dossier de données.
        L'agent doit commencer par ça pour savoir sur quoi il peut travailler.
        """
        if not os.path.exists(DATA_FOLDER):
            return {"error": f"Le dossier {DATA_FOLDER} n'existe pas."}

        files = [
            f for f in os.listdir(DATA_FOLDER) if f.endswith((".csv", ".xlsx", ".xls"))
        ]
        return {
            "count": len(files),
            "files": files,
            "message": "Choisis un fichier et utilise 'inspect_dataset_structure' pour le lire.",
        }

    def inspect_dataset_structure(self, filename: str) -> dict:
        """
        Lit les 5 premières lignes et les noms de colonnes d'un fichier.
        Permet à l'agent de comprendre le contenu (ex: est-ce un budget ? un bilan ?).
        """
        path = os.path.join(DATA_FOLDER, filename)
        if not os.path.exists(path):
            return {"error": "Fichier introuvable."}

        try:
            if filename.endswith(".csv"):
                # Lecture intelligente (séparateur auto)
                try:
                    df = pd.read_csv(path, sep=None, engine="python", nrows=5)
                except:
                    df = pd.read_csv(path, sep=";", nrows=5)
            else:
                df = pd.read_excel(path, nrows=5)

            # Nettoyage des colonnes pour l'IA
            clean_cols = [str(c).strip() for c in df.columns]

            return {
                "filename": filename,
                "columns": clean_cols,
                "preview": df.head(3).to_dict(orient="records"),
                "total_rows_estimate": "Non calculé (preview mode)",
            }
        except Exception as e:
            return {"error": f"Impossible de lire le fichier : {str(e)}"}

    # ------------------------------------------------------------------------
    # 2. ANALYSE UNIVERSELLE (Fonctionne sur n'importe quelle colonne)
    # ------------------------------------------------------------------------
    def analyze_generic_metric(self, filename: str, column_query: str) -> dict:
        """
        Calcule des stats sur n'importe quelle colonne de n'importe quel fichier.
        L'agent doit trouver le nom de la colonne via 'inspect' d'abord.
        """
        path = os.path.join(DATA_FOLDER, filename)

        # 1. Chargement complet
        try:
            if filename.endswith(".csv"):
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except Exception as e:
            return {"error": f"Erreur lecture : {str(e)}"}

        # 2. Recherche de la colonne (Logique floue intégrée)
        # On nettoie tout pour comparer
        df.columns = [str(c).strip().lower() for c in df.columns]
        query = column_query.strip().lower()

        target_col = None
        # Match exact
        if query in df.columns:
            target_col = query
        # Match partiel
        else:
            matches = [c for c in df.columns if query in c]
            if matches:
                target_col = matches[0]

        if not target_col:
            return {
                "error": f"Colonne '{column_query}' introuvable.",
                "available_columns": list(df.columns),
            }

        # 3. Calculs
        # On essaie de convertir en numérique, si ça rate, on analyse comme du texte
        try:
            series = pd.to_numeric(df[target_col], errors="coerce").dropna()
            is_numeric = True
        except:
            series = df[target_col].astype(str)
            is_numeric = False

        if series.empty:
            return {"error": "Colonne vide."}

        if is_numeric:
            return {
                "type": "Numeric Analysis",
                "file": filename,
                "column": target_col,
                "mean": round(series.mean(), 2),
                "max": series.max(),
                "min": series.min(),
                "sum": series.sum(),
                "count": len(series),
            }
        else:
            return {
                "type": "Text Analysis",
                "file": filename,
                "column": target_col,
                "unique_values_count": series.nunique(),
                "most_frequent": series.mode().tolist()[:3],
            }

    # ------------------------------------------------------------------------
    # 3. VISUALISATION GÉNÉRIQUE
    # ------------------------------------------------------------------------
    def plot_generic_trend(
        self, filename: str, date_col_query: str, value_col_query: str
    ) -> dict:
        """
        Génère un graph ASCII pour n'importe quel couple Date/Valeur.
        """
        path = os.path.join(DATA_FOLDER, filename)
        try:
            if filename.endswith(".csv"):
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except:
            return {"error": "Erreur lecture fichier."}

        # Normalisation
        df.columns = [str(c).strip().lower() for c in df.columns]

        # Recherche colonnes
        d_col = next((c for c in df.columns if date_col_query.lower() in c), None)
        v_col = next((c for c in df.columns if value_col_query.lower() in c), None)

        if not d_col or not v_col:
            return {"error": "Colonnes introuvables.", "cols": list(df.columns)}

        # Préparation Données
        df[d_col] = pd.to_datetime(df[d_col], errors="coerce")
        df[v_col] = pd.to_numeric(df[v_col], errors="coerce")
        df = df.dropna(subset=[d_col, v_col]).sort_values(d_col).tail(24)

        vals = df[v_col].values
        if len(vals) == 0:
            return {"error": "Pas de données."}

        # ASCII Chart Generation
        min_v, max_v = vals.min(), vals.max()
        rng = max_v - min_v if max_v != min_v else 1
        chart = []
        chart.append(f"--- Trend: {v_col} ({filename}) ---")

        for d, v in zip(df[d_col], vals):
            height = int(((v - min_v) / rng) * 10)
            bar = "█" * max(height, 1)
            chart.append(f"{d.strftime('%Y-%m')} | {bar} ({v:.2f})")

        return {"plot": "\n".join(chart)}

    def analyze_pareto_distribution(
        self, filename: str, category_col: str, value_col: str
    ) -> dict:
        """
        ANALYSE FINANCIÈRE AVANCÉE (PARETO 80/20).
        Identifie les postes qui pèsent le plus lourd dans un total (ex: Top 5 des dépenses).

        Args:
            filename: Nom du fichier (ex: 'budget.csv').
            category_col: La colonne de groupement (ex: 'Ministère', 'Nature').
            value_col: La colonne numérique à sommer (ex: 'Montant', 'Dépenses').
        """
        path = os.path.join(DATA_FOLDER, filename)

        # 1. Chargement robuste
        try:
            if filename.endswith(".csv"):
                # On tente une lecture "intelligente" du séparateur
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except Exception as e:
            return {"error": f"Impossible de lire le fichier : {str(e)}"}

        # 2. Nettoyage des noms de colonnes (Strip + Lowercase pour la comparaison)
        # On garde les vrais noms pour l'affichage, mais on crée une version nettoyée pour la recherche
        clean_columns = {c.strip().lower(): c for c in df.columns}

        # 3. Recherche des colonnes cibles (Insensible à la casse et aux espaces)
        # On cherche si le mot-clé demandé est *contenu* dans une des colonnes
        real_cat_col = next(
            (
                real
                for clean, real in clean_columns.items()
                if category_col.lower() in clean
            ),
            None,
        )
        real_val_col = next(
            (
                real
                for clean, real in clean_columns.items()
                if value_col.lower() in clean
            ),
            None,
        )

        # ==============================================================================
        # C'EST ICI QUE L'INTELLIGENCE OPÈRE (Gestion d'erreur Auto-Healing)
        # ==============================================================================
        if not real_cat_col or not real_val_col:
            return {
                "error": "Colonnes introuvables.",
                "requested_params": f"Category='{category_col}', Value='{value_col}'",
                "hint": "ERREUR CRITIQUE MAIS CORRIGIBLE. Analyse la liste 'available_columns' ci-dessous. Trouve le nom EXACT qui correspond sémantiquement à ma demande et RELANCE l'outil immédiatement avec ce nom.",
                "available_columns": list(
                    df.columns
                ),  # On donne la carte au trésor à l'IA
            }
        # ==============================================================================

        # 4. Préparation des données numériques
        try:
            # Nettoyage si les chiffres sont en string (ex: "1 000,00")
            if df[real_val_col].dtype == object:
                df[real_val_col] = (
                    df[real_val_col]
                    .astype(str)
                    .str.replace(",", ".", regex=False)
                    .str.replace(r"\s+", "", regex=True)
                )

            df[real_val_col] = pd.to_numeric(df[real_val_col], errors="coerce").fillna(
                0
            )
        except:
            return {
                "error": f"La colonne '{real_val_col}' ne contient pas de chiffres exploitables."
            }

        # 5. Calcul du Pareto
        grouped = (
            df.groupby(real_cat_col)[real_val_col].sum().sort_values(ascending=False)
        )
        total_sum = grouped.sum()

        if total_sum == 0:
            return {"error": "Le total de la colonne est 0."}

        # On prend le Top 5
        top_5 = grouped.head(5)

        # Formatage des résultats pour le LLM
        formatted_results = []
        for cat, val in top_5.items():
            percentage = (val / total_sum) * 100
            formatted_results.append(f"{cat}: {val:,.2f} ({percentage:.1f}%)")

        # Calcul du "Reste"
        others_val = total_sum - top_5.sum()
        others_perc = (others_val / total_sum) * 100

        return {
            "status": "Success",
            "analysis_title": f"Top 5 contributeurs pour '{real_val_col}' par '{real_cat_col}'",
            "total_global": total_sum,
            "top_5_breakdown": formatted_results,
            "others": f"Autres postes : {others_val:,.2f} ({others_perc:.1f}%)",
            "key_insight": f"Les 5 premiers postes représentent {top_5.sum()/total_sum:.1%} du total.",
        }

    def calculate_growth_trend(
        self, filename: str, date_col: str, value_col: str
    ) -> dict:
        """
        ANALYSE DE TENDANCE : Calcule la variation (croissance ou baisse) entre le début et la fin de la période.
        Utile pour répondre à : "Quelle est la tendance globale ?" ou "De combien ça a augmenté ?".
        """
        # (Chargement...)
        path = os.path.join(DATA_FOLDER, filename)
        try:
            if filename.endswith(".csv"):
                df = pd.read_csv(path, sep=None, engine="python")
            else:
                df = pd.read_excel(path)
        except:
            return {"error": "Erreur lecture."}

        # Nettoyage et tri
        df.columns = [str(c).strip().lower() for c in df.columns]
        d_c = next((c for c in df.columns if date_col.lower() in c), None)
        v_c = next((c for c in df.columns if value_col.lower() in c), None)

        if not d_c or not v_c:
            return {"error": "Colonnes introuvables."}

        df[d_c] = pd.to_datetime(df[d_c], errors="coerce")
        df[v_c] = pd.to_numeric(df[v_c], errors="coerce")
        df = df.dropna(subset=[d_c, v_c]).sort_values(d_c)

        if len(df) < 2:
            return {"error": "Pas assez de données."}

        first_val = df[v_c].iloc[0]
        last_val = df[v_c].iloc[-1]

        # Calcul du CAGR (Taux de croissance global) ou variation simple
        if first_val == 0:
            variation = 0
        else:
            variation = ((last_val - first_val) / abs(first_val)) * 100

        trend = "Hausse" if variation > 0 else "Baisse"

        return {
            "type": "Trend Analysis",
            "start_date": str(df[d_c].iloc[0].date()),
            "end_date": str(df[d_c].iloc[-1].date()),
            "start_value": first_val,
            "end_value": last_val,
            "variation_percentage": round(variation, 2),
            "trend_direction": trend,
        }
